with c as (select id from public.academy_courses where id='meteorology-forecasting-foundations'),
ch as (insert into public.academy_chapters(course_id,title,description,sort_order,published) select id,'إدارة البيانات والأدوات الرقمية للأرصاد الجوية','صيغ البيانات الجوية والمعايير والبرمجة والتحليل المكاني وجودة البيانات وقواعد البيانات والأتمتة والمنتجات البصرية.',17,false from c on conflict(course_id,title) do update set description=excluded.description returning id),
u1 as (insert into public.academy_units(chapter_id,title,sort_order,published) select id,'صيغ البيانات وتبادلها',1,false from ch on conflict(chapter_id,title) do update set sort_order=excluded.sort_order returning id),
u2 as (insert into public.academy_units(chapter_id,title,sort_order,published) select id,'جودة البيانات وإدارتها',2,false from ch on conflict(chapter_id,title) do update set sort_order=excluded.sort_order returning id),
u3 as (insert into public.academy_units(chapter_id,title,sort_order,published) select id,'التحليل المكاني والخرائط',3,false from ch on conflict(chapter_id,title) do update set sort_order=excluded.sort_order returning id),
u4 as (insert into public.academy_units(chapter_id,title,sort_order,published) select id,'البرمجة والتحليل العلمي',4,false from ch on conflict(chapter_id,title) do update set sort_order=excluded.sort_order returning id),
u5 as (insert into public.academy_units(chapter_id,title,sort_order,published) select id,'إدارة قواعد البيانات والتشغيل',5,false from ch on conflict(chapter_id,title) do update set sort_order=excluded.sort_order returning id),
d(slug,title,summary,content,ord,mins,objectives,unit) as (values ('meteorological-data-formats-and-standards','صيغ البيانات الجوية والمعايير الدولية','التعرف إلى صيغ تبادل بيانات الأرصاد والخرائط والشبكات الرقمية.','{"blocks":[{"type":"text","text":"تتنوع بيانات الأرصاد بين قياسات محطات نقطية وخرائط شبكية وصور رادارية وفضائية وسلاسل زمنية."},{"type":"text","text":"يصف ملف CSV بيانات جدولية بسيطة، لكنه لا يحمل وحده جميع البيانات الوصفية المكانية والزمنية اللازمة للمنتجات المعقدة."},{"type":"text","text":"تستخدم NetCDF على نطاق واسع لتخزين متغيرات علمية متعددة الأبعاد مع إحداثيات وبيانات وصفية."},{"type":"text","text":"تستخدم GRIB لتبادل بيانات التنبؤ العددي والحقول الجوية وفق جداول ترميز معتمدة."},{"type":"text","text":"يستخدم BUFR لتبادل مشاهدات الأرصاد المشفرة بكفاءة، ويعتمد فكها على جداول ومواصفات الرسائل."},{"type":"text","text":"تتطلب ملفات الصور الجغرافية مثل GeoTIFF معلومات الإسناد المكاني ونظام الإحداثيات."},{"type":"text","text":"يجب التمييز بين قيمة المتغير ووحدته وزمنه وموقعه وارتفاع القياس وطريقة إنتاجه."},{"type":"text","text":"تضمن المعايير المشتركة تفسير البيانات بين المؤسسات والأنظمة المختلفة بصورة متسقة."},{"type":"text","text":"قد تختلف إصدارات الصيغ وجداول الترميز، لذلك يجب توثيق الإصدار والمنتج ومصدر البيانات."},{"type":"text","text":"تساعد البيانات الوصفية على معرفة التغطية الزمنية والمكانية وجودة القياسات والقيود."},{"type":"text","text":"مثال: لا تكفي قراءة قيمة حرارة من ملف شبكي دون معرفة الإحداثيات والوحدة والتوقيت ومستوى الضغط."},{"type":"callout","text":"خلاصة: الصيغة والمعيار والبيانات الوصفية عناصر أساسية لقابلية تبادل البيانات الجوية وإعادة استخدامها."}]}',960,55,'["تمييز صيغ البيانات الجوية","فهم البيانات الشبكية والنقطية","شرح أهمية المعايير"]','صيغ البيانات وتبادلها'),
('synop-metar-and-observation-codes','رسائل SYNOP وMETAR وشفرة تقارير الرصد','بنية تقارير المحطات السطحية وتقارير المطارات والرموز التشغيلية.','{"blocks":[{"type":"text","text":"تستخدم رسائل SYNOP لتبادل مشاهدات سطحية متزامنة ضمن شبكات الرصد الدولية وفق قواعد ترميز محددة."},{"type":"text","text":"تستخدم METAR لتقديم تقرير رصد جوي روتيني للمطارات، ويتضمن عناصر الطقس المهمة للطيران."},{"type":"text","text":"تستخدم SPECI لإصدار تقرير خاص عند حدوث تغيرات جوية تستوفي معايير محددة في المطار."},{"type":"text","text":"تتضمن تقارير METAR عادة رمز المطار ووقت الرصد والرياح والرؤية والظواهر الحالية والسحب والحرارة والضغط."},{"type":"text","text":"يكتب وقت الرصد عادة بالتوقيت العالمي UTC لتوحيد التبادل بين المحطات والمستخدمين."},{"type":"text","text":"تصف مجموعة الرياح الاتجاه والسرعة والهبات عند توافرها، ويجب تفسير الوحدات والرموز كما وردت في التقرير."},{"type":"text","text":"تصف مجموعات الرؤية مدى الرؤية الأفقية وفق اصطلاحات التقرير والمنطقة."},{"type":"text","text":"تستخدم رموز الطقس الحالي لوصف الهطول والضباب والعواصف والغبار وظواهر أخرى وفق جداول معيارية."},{"type":"text","text":"تعرض مجموعات السحب مقدار التغطية وارتفاع القاعدة ونوع السحب المهمة للطيران."},{"type":"text","text":"تتطلب قراءة الضغط والحرارة فهم رمز المجموعة والوحدة وقواعد الترميز المعتمدة."},{"type":"text","text":"قد تختلف بعض المجموعات الاختيارية حسب الدولة ونوع المحطة وإصدار المعيار."},{"type":"text","text":"مثال: قبل تفسير تقرير METAR تحقق من وقت الرصد ورمز المطار ووحدات الرياح والضغط."},{"type":"callout","text":"خلاصة: قراءة تقارير الرصد تتطلب معرفة بنية الرسالة والتوقيت والرموز والاختلافات التشغيلية."}]}',970,55,'["تمييز SYNOP وMETAR وSPECI","قراءة عناصر التقرير الأساسية","فهم توقيت الرصد والشفرة"]','صيغ البيانات وتبادلها'),
('advanced-meteorological-quality-control','التحقق المتقدم من جودة بيانات الأرصاد','قواعد الاتساق المكاني والزمني واكتشاف الشذوذ ومؤشرات جودة القياس.','{"blocks":[{"type":"text","text":"تبدأ مراقبة الجودة بفحص اكتمال السجل وصحة التوقيت والموقع والوحدات والبيانات الوصفية."},{"type":"text","text":"يكشف اختبار المجال القيم التي تقع خارج الحدود الفيزيائية أو التشغيلية المتوقعة للمتغير."},{"type":"text","text":"يكشف اختبار التغير الزمني القفزات غير المعتادة بين قياسين متتاليين مع مراعاة طبيعة المتغير والفترة."},{"type":"text","text":"يفحص اختبار الاستمرارية بقاء قيمة ثابتة مدة طويلة بصورة غير متوقعة، وقد يشير إلى تجمد حساس أو مشكلة اتصال."},{"type":"text","text":"يقارن اختبار الاتساق الداخلي متغيرات مترابطة مثل الحرارة ونقطة الندى والرطوبة النسبية."},{"type":"text","text":"يقارن الاختبار المكاني القياس بمحطات مجاورة أو حقول تحليلية، مع مراعاة التضاريس والاختلافات المحلية."},{"type":"text","text":"تساعد اختبارات التكرار واكتشاف الرسائل المكررة على منع مضاعفة السجلات في قواعد البيانات."},{"type":"text","text":"يجب ألا يحذف النظام القيم الشاذة آلياً دون الاحتفاظ بالأصل وتسجيل سبب الرفض أو التحذير."},{"type":"text","text":"تستخدم أعلام الجودة لتمييز البيانات المقبولة والمشكوك فيها والمفقودة والمصححة وفق قاموس موحد."},{"type":"text","text":"يجب اختبار قواعد الجودة على حالات موسمية ومناخية مختلفة لتجنب رفض الظواهر الحقيقية النادرة."},{"type":"text","text":"مثال: قراءة مطر مرتفعة قد تكون حدثاً حقيقياً؛ تقارن بالرادار والمحطات المجاورة وسجل الحساس قبل رفضها."},{"type":"callout","text":"خلاصة: مراقبة الجودة توازن بين كشف أخطاء القياس والحفاظ على الأحداث الجوية الحقيقية."}]}',980,55,'["تمييز اختبارات الجودة","فهم الاتساق الداخلي والمكاني","توثيق أعلام الجودة"]','جودة البيانات وإدارتها'),
('gis-and-spatial-meteorology','نظم المعلومات الجغرافية والتحليل المكاني للأرصاد','الإحداثيات والإسقاطات والاستيفاء وتحليل التوزيع المكاني للمتغيرات الجوية.','{"blocks":[{"type":"text","text":"تربط نظم المعلومات الجغرافية البيانات الجوية بمواقعها الجغرافية لعرضها وتحليلها ومقارنتها بخصائص السطح."},{"type":"text","text":"تحدد الإحداثيات الجغرافية الموقع بخط العرض والطول، بينما تستخدم الإسقاطات تمثيلاً مستوياً لسطح الأرض."},{"type":"text","text":"يؤدي اختيار الإسقاط غير المناسب إلى تشوه المسافات أو المساحات أو الاتجاهات بحسب نوع الإسقاط ومجال الاستخدام."},{"type":"text","text":"تمثل المحطات بيانات نقطية، بينما تمثل النماذج العددية كثيراً من المتغيرات على شبكات مكانية."},{"type":"text","text":"تستخدم البيانات المتجهة لتمثيل النقاط والخطوط والمضلعات مثل مواقع المحطات والأحواض والحدود الإدارية."},{"type":"text","text":"تستخدم البيانات النقطية والشبكية لتمثيل صور الأقمار والارتفاعات وحقول الحرارة والهطول."},{"type":"text","text":"يقدر الاستيفاء المكاني قيماً بين مواقع القياس، وتعتمد موثوقيته على كثافة المحطات والتضاريس والبنية المكانية."},{"type":"text","text":"تشمل طرق الاستيفاء المسافة العكسية الموزونة وKriging وطرقاً أخرى، ولكل منها افتراضات وحدود."},{"type":"text","text":"يجب توحيد نظام الإحداثيات والوحدات وحجم الخلية قبل إجراء المقارنات أو العمليات المكانية."},{"type":"text","text":"تساعد نماذج الارتفاع الرقمية في تحليل أثر التضاريس والارتفاع واتجاه المنحدر على التوزيع الجوي."},{"type":"text","text":"مثال: خريطة مطر مستوفاة من محطات قليلة في منطقة جبلية قد تخفي التباين الحقيقي بين السفوح والوديان."},{"type":"callout","text":"خلاصة: التحليل المكاني لا يعوض نقص الرصد، بل يحتاج فهماً لحدود البيانات وطريقة الاستيفاء والإسقاط."}]}',990,55,'["شرح نظم الإحداثيات والإسقاطات","تمييز البيانات النقطية والشبكية","فهم حدود الاستيفاء المكاني"]','التحليل المكاني والخرائط'),
('python-for-meteorological-data-analysis','استخدام Python في تحليل بيانات الأرصاد','مبادئ تنظيم البيانات العلمية وتحليلها وإنتاج الرسوم باستخدام أدوات Python.','{"blocks":[{"type":"text","text":"تستخدم Python في قراءة بيانات المحطات والنماذج وتنظيفها وتحليلها وإنتاج منتجات رسومية."},{"type":"text","text":"تساعد مكتبة pandas في التعامل مع الجداول والسلاسل الزمنية والدمج والتجميع."},{"type":"text","text":"تستخدم NumPy للحسابات العددية والمصفوفات والعمليات المتجهة بكفاءة."},{"type":"text","text":"تستخدم Matplotlib لإنتاج الرسوم الزمنية والمخططات التوزيعية والخرائط الأساسية عند دمجها بأدوات مكانية مناسبة."},{"type":"text","text":"تساعد xarray في التعامل مع البيانات العلمية متعددة الأبعاد مثل حقول النماذج على شبكات زمنية ومكانية."},{"type":"text","text":"يجب تحويل التوقيت إلى مرجع موحد وتوثيق المنطقة الزمنية قبل دمج مصادر متعددة."},{"type":"text","text":"ينبغي توحيد الوحدات قبل إجراء العمليات الحسابية والمقارنات بين المتغيرات."},{"type":"text","text":"تستخدم الأقنعة والقيم المفقودة لمعالجة البيانات الناقصة دون استبدالها بقيم مضللة."},{"type":"text","text":"يفضل حفظ خطوات المعالجة في نص برمجي موثق بدلاً من تعديلات يدوية غير قابلة للتكرار."},{"type":"text","text":"يجب توثيق مصدر البيانات وإصدار المكتبات ومعلمات التحليل لإعادة إنتاج النتائج."},{"type":"text","text":"مثال: يمكن تجميع قياسات الحرارة بالساعة إلى متوسطات يومية بعد التحقق من اكتمال الساعات والوحدات والتوقيت."},{"type":"callout","text":"خلاصة: البرمجة العلمية تزيد كفاءة التحليل بشرط توثيق المصدر والمعالجة والتحقق من النتائج."}]}',1000,55,'["فهم سير تحليل البيانات","التعرف إلى مكتبات البيانات العلمية","إنتاج ملخصات ورسوم قابلة للتكرار"]','البرمجة والتحليل العلمي'),
('time-series-cleaning-and-gap-handling','تنظيف السلاسل الزمنية ومعالجة الفجوات','توحيد التوقيت واكتشاف التكرار والفقد والاستيفاء الزمني وحدوده.','{"blocks":[{"type":"text","text":"تحتاج السلاسل الزمنية إلى ترتيب زمني موحد وفاصل قياس معروف قبل التحليل."},{"type":"text","text":"قد تنتج الفجوات من انقطاع الاتصال أو تعطل الحساس أو فقد الرسائل أو استبعاد قياسات منخفضة الجودة."},{"type":"text","text":"يجب التمييز بين القيمة المفقودة والصفر؛ فغياب المطر لا يساوي غياب القياس."},{"type":"text","text":"قد تتكرر الرسائل عند إعادة الإرسال، ولذلك يجب تعريف مفتاح فريد يميز المحطة والمتغير ووقت الرصد."},{"type":"text","text":"تساعد إعادة أخذ العينات الزمنية على تحويل السجل إلى فواصل منتظمة، لكنها لا تخلق قياسات لم تحدث."},{"type":"text","text":"قد يناسب الاستيفاء الخطي فجوات قصيرة لبعض المتغيرات الهادئة، لكنه لا يمثل التغيرات السريعة أو الأحداث القصوى بدقة."},{"type":"text","text":"تحتاج متغيرات الهطول والبرق والهبات إلى عناية خاصة لأن الاستيفاء قد يخفي القمم أو يخلق قيماً غير واقعية."},{"type":"text","text":"يمكن استخدام بيانات محطات مجاورة أو منتجات تحليلية للمساعدة في تقدير الفجوات، مع وسم القيم المقدرة بوضوح."},{"type":"text","text":"يجب حفظ القيمة الأصلية وحالة الجودة ومصدر أي قيمة معوضة في سجل منفصل أو أعمدة واضحة."},{"type":"text","text":"تؤثر نسبة الفقد وموقعه الزمني في صلاحية المتوسطات والمؤشرات، ويجب الإفصاح عنها."},{"type":"text","text":"مثال: لا يصح ملء فجوة مطر خلال عاصفة بخط مستقيم بين صفرين؛ فقد يؤدي ذلك إلى فقد الحدث بالكامل."},{"type":"callout","text":"خلاصة: معالجة الفجوات قرار علمي يعتمد على المتغير وطول الفجوة والغرض من التحليل."}]}',1010,55,'["اكتشاف الفجوات والتكرار","فهم طرق معالجة القيم المفقودة","تقييم أثر الاستيفاء"]','البرمجة والتحليل العلمي'),
('satellite-radar-data-processing','معالجة بيانات الأقمار الصناعية والرادار','مبادئ قراءة الملفات الشبكية والتحويلات والمعايرة والمنتجات المشتقة.','{"blocks":[{"type":"text","text":"تبدأ معالجة بيانات الأقمار والرادار بفهم نوع المنتج والوحدة والتوقيت والإحداثيات ودقة الشبكة."},{"type":"text","text":"تحتاج الصور الخام أو القياسات الأولية إلى معايرة وتحويلات هندسية قبل إنتاج بعض المنتجات العلمية."},{"type":"text","text":"تربط المعالجة الجغرافية البكسل بموقعه على الأرض، وقد تتطلب تصحيحاً هندسياً أو إعادة إسقاط."},{"type":"text","text":"تحتوي القنوات الطيفية على قياسات إشعاعية أو منتجات مشتقة، ولا ينبغي تفسير القيم الرقمية دون معرفة معايرتها."},{"type":"text","text":"تنتج درجة حرارة السطوع من قياسات الأشعة تحت الحمراء وفق المعالجة المعتمدة، ولا تساوي دائماً حرارة الهواء قرب السطح."},{"type":"text","text":"تعبر انعكاسية الرادار عن شدة الإشارة المرتدة، وتتأثر بحجم الهيدروميتورات وشكلها وتركيزها وطول الموجة."},{"type":"text","text":"يتطلب تقدير معدل المطر من الرادار علاقة تحويل ومعايرة مقارنة بمقاييس أرضية، وتختلف العلاقة باختلاف نوع الهطول."},{"type":"text","text":"قد تظهر أخطاء بسبب التوهين والحجب الأرضي والضوضاء والتداخل والعيوب الهندسية."},{"type":"text","text":"تستخدم أقنعة الجودة لإظهار المناطق غير الموثوقة أو المتأثرة بمشكلات الاستشعار."},{"type":"text","text":"يجب الاحتفاظ بمعلومات المنتج الأصلي ووقت المعالجة وإصدار الخوارزمية عند إنشاء منتج مشتق."},{"type":"text","text":"مثال: مقارنة منتج هطول فضائي بمقياس مطر تساعد على كشف الانحياز، لكنها تحتاج مطابقة زمنية ومكانية مناسبة."},{"type":"callout","text":"خلاصة: جودة المنتج المشتق تعتمد على فهم القياس الأصلي والمعايرة والخوارزمية والقيود."}]}',1020,55,'["فهم المعالجة الأولية للبيانات","تمييز القياس عن المنتج المشتق","التعرف إلى مصادر الخطأ"]','التحليل المكاني والخرائط'),
('meteorological-data-apis-and-automation','واجهات API وأتمتة تدفق البيانات الجوية','جلب البيانات المجدولة والتحقق منها وتحويلها وتخزينها بصورة قابلة للتتبع.','{"blocks":[{"type":"text","text":"تتيح واجهات API تبادل البيانات بين أنظمة الرصد وقواعد البيانات والتطبيقات وفق عقود وطرق وصول محددة."},{"type":"text","text":"يجب توثيق نقطة الوصول والمعلمات والوحدات وحدود الطلب ومصدر البيانات وشروط الاستخدام."},{"type":"text","text":"تستخدم الاستجابات المنظمة مثل JSON أو XML لنقل القياسات والبيانات الوصفية."},{"type":"text","text":"تحتاج عملية الجلب إلى معالجة حالات انتهاء المهلة وأخطاء الشبكة والحدود المفروضة على الطلبات."},{"type":"text","text":"ينبغي استخدام معرفات المحطات والأوقات والمتغيرات كمفاتيح واضحة لتجنب تكرار السجلات."},{"type":"text","text":"تتكون سلسلة المعالجة غالباً من الجلب والتحقق والتحويل والتخزين وإنتاج مؤشرات حالة التشغيل."},{"type":"text","text":"يجب أن تكون عمليات الإدخال قابلة لإعادة التنفيذ دون مضاعفة السجلات، باستخدام مفاتيح فريدة وسياسات upsert مناسبة."},{"type":"text","text":"تسجل سجلات التشغيل وقت الجلب وعدد السجلات المقبولة والمرفوضة وأسباب الفشل."},{"type":"text","text":"ينبغي فصل أسرار الاتصال عن الشيفرة العامة واستخدام أقل صلاحية لازمة لكل خدمة."},{"type":"text","text":"تساعد المراقبة والتنبيهات على اكتشاف توقف المصدر أو تأخر البيانات أو تغير بنية الاستجابة."},{"type":"text","text":"مثال: عند إعادة محاولة جلب ساعة فشلت سابقاً، يجب ألا يؤدي ذلك إلى إدخال قياسات مكررة."},{"type":"callout","text":"خلاصة: الأتمتة الموثوقة تجمع التحقق والتتبع والأمان وإمكانية إعادة التنفيذ."}]}',1030,55,'["شرح دورة تدفق البيانات","فهم طلبات API والاستجابات","تصميم معالجة قابلة للتتبع"]','إدارة قواعد البيانات والتشغيل'),
('meteorological-databases-and-archiving','قواعد بيانات الأرصاد والأرشفة طويلة الأمد','تصميم تخزين زمني ومكاني موحد وحفظ السجلات والبيانات الوصفية.','{"blocks":[{"type":"text","text":"تحتاج قاعدة بيانات الأرصاد إلى تمثيل المحطة والمتغير ووقت القياس والقيمة والوحدة وحالة الجودة."},{"type":"text","text":"يفضل فصل تعريف المحطة وبياناتها الوصفية عن القياسات المتكررة لتقليل التكرار وتحسين الاتساق."},{"type":"text","text":"تستخدم مفاتيح فريدة مثل معرف المحطة والمتغير ووقت الرصد لمنع تكرار القياسات."},{"type":"text","text":"تساعد الفهارس الزمنية والمكانية في تسريع الاستعلامات حسب المحطة والفترة والمنطقة."},{"type":"text","text":"يجب تخزين التوقيت بمرجع موحد مع حفظ المنطقة الزمنية الأصلية عند الحاجة."},{"type":"text","text":"تحتاج البيانات إلى وحدات معيارية وقاموس أسماء متغيرات يوضح التعريف والوحدة والارتفاع المرجعي."},{"type":"text","text":"ينبغي الاحتفاظ بمصدر البيانات وإصدار المعالجة وحالة الجودة وتاريخ التعديل."},{"type":"text","text":"تدعم الأرشفة طويلة الأمد حفظ البيانات الخام والبيانات المعالجة والمنتجات النهائية بصورة منفصلة ومترابطة."},{"type":"text","text":"تحتاج النسخ الاحتياطية إلى اختبار استعادة دوري، فوجود نسخة لا يثبت إمكانية استرجاعها."},{"type":"text","text":"تحدد سياسات الاحتفاظ وإدارة الإصدارات كيفية حفظ السجلات الأصلية والتعديلات دون فقد تاريخها."},{"type":"text","text":"مثال: يمكن إعادة إنتاج خريطة مناخية إذا حفظت البيانات الخام والنسخة المنظفة والكود ومعلمات التحليل."},{"type":"callout","text":"خلاصة: الأرشفة العلمية تحفظ القيمة والبيانات الوصفية وتاريخ المعالجة وإمكانية إعادة الإنتاج."}]}',1040,55,'["فهم نموذج تخزين بيانات المحطات","تصميم مفاتيح وفهارس مناسبة","شرح الأرشفة والنسخ الاحتياطي"]','إدارة قواعد البيانات والتشغيل'),
('meteorological-visualization-and-dashboards','تصميم الرسوم والخرائط ولوحات المعلومات الجوية','مبادئ العرض العلمي للسلاسل والخرائط والمؤشرات ومراقبة التشغيل.','{"blocks":[{"type":"text","text":"يحول التصوير البياني بيانات الأرصاد إلى أنماط مفهومة تساعد على التحليل واتخاذ القرار."},{"type":"text","text":"تستخدم السلاسل الزمنية لعرض تغير الحرارة والضغط والرياح والهطول مع توضيح الوحدات والتوقيت."},{"type":"text","text":"تستخدم المدرجات التكرارية والصندوقية لفهم التوزيع والتشتت والقيم الشاذة."},{"type":"text","text":"تحتاج الخرائط إلى عنوان ومفتاح ألوان ووحدة ومقياس زمني ومصدر وتاريخ إصدار واضح."},{"type":"text","text":"يجب اختيار تدرج لوني مناسب للمتغير وتجنب الألوان المتشابهة التي تخفي الفروق المهمة."},{"type":"text","text":"تستخدم خطوط تساوي الضغط والارتفاع والحرارة لعرض الحقول المستمرة، مع توضيح مستوى الضغط أو الارتفاع."},{"type":"text","text":"تساعد المقاطع الرأسية والرسوم الحرارية في فهم البنية الرأسية للغلاف الجوي."},{"type":"text","text":"تعرض لوحات التشغيل حالة وصول البيانات وحداثتها ونسبة الاكتمال وأعلام الجودة وأعطال المصادر."},{"type":"text","text":"ينبغي الفصل بصرياً بين المشاهدة والتنبؤ والمنتج التحليلي حتى لا يختلط مصدر المعلومة."},{"type":"text","text":"يجب ألا توحي دقة الرسم بدقة أعلى من دقة البيانات الأصلية أو طريقة الاستيفاء."},{"type":"text","text":"مثال: خريطة مطر تراكمية يجب أن تعرض فترة التجميع ووحدة mm ومصدر المنتج ووقت آخر تحديث."},{"type":"callout","text":"خلاصة: لوحة الأرصاد الجيدة دقيقة وواضحة وتعرض مصدر البيانات وحدودها وحالة حداثتها."}]}',1050,55,'["اختيار الرسم المناسب للمتغير","تصميم خريطة جوية مقروءة","عرض حالة البيانات بوضوح"]','التحليل المكاني والخرائط'))
insert into public.academy_lessons(course_id,chapter_id,unit_id,slug,title,summary,content,published,sort_order,level,estimated_minutes,learning_objectives,chapter_title,unit_title)
select c.id,ch.id,case d.unit when 'صيغ البيانات وتبادلها' then u1.id when 'جودة البيانات وإدارتها' then u2.id when 'التحليل المكاني والخرائط' then u3.id when 'البرمجة والتحليل العلمي' then u4.id when 'إدارة قواعد البيانات والتشغيل' then u5.id end,d.slug,d.title,d.summary,d.content::jsonb,false,d.ord,'advanced',d.mins,d.objectives::jsonb,'إدارة البيانات والأدوات الرقمية للأرصاد الجوية',d.unit from d cross join c cross join ch cross join u1 cross join u2 cross join u3 cross join u4 cross join u5
on conflict(course_id,slug) do update set chapter_id=excluded.chapter_id,unit_id=excluded.unit_id,title=excluded.title,summary=excluded.summary,content=excluded.content,published=false,sort_order=excluded.sort_order,level=excluded.level,estimated_minutes=excluded.estimated_minutes,learning_objectives=excluded.learning_objectives,chapter_title=excluded.chapter_title,unit_title=excluded.unit_title;